import { createClient as createClient3 } from "npm:@supabase/supabase-js@^2.52.1";
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.24.0";
import { z as z3 } from "npm:zod@^4.4.3";
var create_onramp_default = defineTool3({
  name: "create_onramp_request",
  title: "Create onramp request",
  description: "Create a new onramp request (Mobile Money XOF -> stablecoin) on behalf of the signed-in user. Delegates to the create-onramp-request edge function, then tags the created row with the user's id.",
  inputSchema: {
    xofAmount: z3.number().min(100).max(6e5),
    token: z3.enum(["USDC", "USDT"]),
    network: z3.string().describe("Blockchain network, e.g. base, bsc, ethereum, polygon, solana."),
    recipientAddress: z3.string().min(1).max(64).describe("Destination wallet address."),
    momoNumber: z3.string().min(8).max(20),
    momoProvider: z3.string().optional(),
    countryId: z3.string().uuid().optional()
  },
  annotations: { readOnlyHint: false, destructiveHint: false, openWorldHint: false },
  handler: async (input, ctx) => {
    if (!ctx.isAuthenticated()) {
      return { content: [{ type: "text", text: "Not authenticated" }], isError: true };
    }
    const url = process.env.SUPABASE_URL;
    const key = process.env.SUPABASE_PUBLISHABLE_KEY ?? process.env.SUPABASE_ANON_KEY;
    const res = await fetch(`${url}/functions/v1/create-onramp-request`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        apikey: key,
        Authorization: `Bearer ${key}`
      },
      body: JSON.stringify(input)
    });
    const body = await res.json();
    if (!res.ok || !body?.success) {
      return {
        content: [{ type: "text", text: body?.details || body?.error || "Failed to create onramp request" }],
        isError: true
      };
    }
    const service = createClient3(url, process.env.SUPABASE_SERVICE_ROLE_KEY, {
      auth: { persistSession: false, autoRefreshToken: false }
    });
    if (body.data?.id) {
      await service.from("onramp_requests").update({ user_id: ctx.getUserId() }).eq("id", body.data.id);
    }
    return {
      content: [{ type: "text", text: JSON.stringify(body.data) }],
      structuredContent: body.data
    };
  }
});

